rows=[]
for i,(kind,name,decision,why) in enumerate(ITEMS,1):
 f=next(x for x in json.loads((R/'evidence'/kind/'functions.json').read_text()) if x['name']==name)
 ev=[]
 for v in ('r155','new'):
  if f[v]:ev.append(f"evidence/{kind}/{v}/disassembly.txt:{f[v]['line']}")
 rows.append(dict(rank=i,component=kind,name=name,disposition=decision,basis=why,evidence=ev,diff=f.get('diff'),runtime_causality='unverified'))
(R/'top20.json').write_text(json.dumps(rows,indent=2)+'\n')
lines=['# First 20 function assessments (task56 corrected baseline)', '', 'Provider compares sealed R155 80c9aee0 against NEW 8d109259. All task52 NEW hashes still differ; old hashes now match. The earlier 977fb347 provider judgments are superseded. Restore means R155 parity, not proven crash causality. See RESTORE-PLAN.md.', '']
for x in rows:
 lines += [f"## {x['rank']}. {x['component']}: `{x['name']}` — {x['disposition']}", '',x['basis'],'', 'Evidence: '+', '.join(f"`{s}`" for s in x['evidence'])+(f"; [{x['diff']}]({x['diff']})." if x['diff'] else "; normalized instructions equal."),'']
(R/'TOP20.md').write_text('\n'.join(lines))
